runnerTemplate:
// Run ONE batch per use_figma call. Prepend const PANEL, BATCH, NODE_MAP with literal JSON.
// NODE_MAP maps ORIGINAL IDs to the matching nodes inside one cloned panel.
const page = await figma.getNodeByIdAsync("0:1");
await figma.setCurrentPageAsync(page);
if (!BATCH.mutations.length || BATCH.mutations.length > 10) throw new Error("Batch must contain 1-10 mutations");
const cloneRootId = NODE_MAP[PANEL.sourceRootId];
if (!cloneRootId || cloneRootId === PANEL.sourceRootId) throw new Error("Clone root mapping required");
const cloneRoot = await figma.getNodeByIdAsync(cloneRootId);
if (!cloneRoot) throw new Error("Clone root missing");
const nodes = [];
for (const m of BATCH.mutations) {
  const targetId = NODE_MAP[m.sourceId];
  if (!targetId || targetId === m.sourceId) throw new Error("Refuse to modify original: " + m.sourceId);
  const node = await figma.getNodeByIdAsync(targetId);
  if (!node || node.type !== m.expectedType) throw new Error("Unexpected target type: " + m.sourceId);
  let ancestor = node; let insideClone = false;
  while (ancestor) { if (ancestor.id === cloneRootId) { insideClone = true; break; } ancestor = ancestor.parent; }
  if (!insideClone) throw new Error("Target outside clone: " + targetId);
  nodes.push({ m, node });
}
// Attempt all current fonts first, then load verified replacements.
const unavailableCurrentFonts = [];
const currentFonts = new Map();
for (const { node } of nodes) {
  const texts = node.type === "TEXT" ? [node] : ("findAllWithCriteria" in node ? node.findAllWithCriteria({types:["TEXT"]}) : []);
  for (const t of texts) for (const s of t.getStyledTextSegments(["fontName"])) currentFonts.set(JSON.stringify(s.fontName), s.fontName);
}
for (const [key, font] of currentFonts) {
  try { await figma.loadFontAsync(font); } catch (e) { unavailableCurrentFonts.push({font, reason:String(e)}); }
}
await figma.loadFontAsync({family:"Noto Sans SC",style:"Regular"});
await figma.loadFontAsync({family:"Noto Sans SC",style:"Medium"});
const mutatedNodeIds = [];
const results = [];
for (const { m, node } of nodes) {
  // On text, assign the loaded replacement font before all remaining text properties.
  if (node.type === "TEXT" && m.props.fontName) node.fontName = m.props.fontName;
  const props = { ...m.props }; delete props.fontName;
  node.set(props);
  if (m.resize) node.resize(m.resize.width, m.resize.height);
  if (m.postProps) node.set(m.postProps);
  if (m.assertions) {
    if (m.assertions.heightMax !== undefined && node.height > m.assertions.heightMax) throw new Error("Text reflow needs layout adjustment: " + node.id);
    if (m.assertions.widthMin !== undefined && node.width < m.assertions.widthMin) throw new Error("Text width collapsed: " + node.id);
    if (m.assertions.characters !== undefined && node.characters !== m.assertions.characters) throw new Error("Filename content changed: " + node.id);
  }
  mutatedNodeIds.push(node.id);
  results.push({sourceId:m.sourceId,id:node.id,type:node.type,width:node.width,height:node.height});
}
return {batchId:BATCH.id,mutatedNodeIds,results,unavailableCurrentFonts};
